WITH RankedPosts AS (SELECT p.Id AS PostId, p.Title, p.CreationDate, p.Score, p.ViewCount, p.AnswerCount, RANK() OVER (PARTITION BY p.PostTypeId ORDER BY p.Score DESC NULLS FIRST) AS RankInType FROM Posts AS p WHERE p.CreationDate >= CAST('2024-10-01 12:34:56' AS Nullable(DateTime)) - INTERVAL '1' YEAR), TopUsers AS (SELECT u.Id AS UserId, u.DisplayName, SUM(v.BountyAmount) AS TotalBounties, COUNT(DISTINCT p.Id) AS TotalPosts, AVG(u.Reputation) AS AvgReputation FROM Users AS u JOIN Posts AS p ON u.Id = p.OwnerUserId LEFT JOIN Votes AS v ON u.Id = v.UserId GROUP BY u.Id, u.DisplayName HAVING COUNT(DISTINCT p.Id) > 5), ClosedPosts AS (SELECT ph.PostId, COUNT(ph.Id) AS CloseCount, GROUP_CONCAT(ct.Name, ', ') AS CloseReasons FROM PostHistory AS ph JOIN CloseReasonTypes AS ct ON CAST(ph.Comment AS Nullable(Int32)) = ct.Id WHERE ph.PostHistoryTypeId IN (10, 11) GROUP BY ph.PostId) SELECT rp.PostId, rp.Title, rp.Score, rp.ViewCount, rp.AnswerCount, tu.TotalBounties, tu.TotalPosts, tu.AvgReputation, cp.CloseCount, cp.CloseReasons FROM RankedPosts AS rp LEFT JOIN TopUsers AS tu ON rp.PostId = tu.UserId LEFT JOIN ClosedPosts AS cp ON rp.PostId = cp.PostId WHERE rp.RankInType <= 10 ORDER BY rp.Score DESC NULLS FIRST, tu.TotalBounties DESC